// Memory-Mapped Register Bit Manipulation in C
#define PORTB_DIR (*((volatile uint8_t *)0x24))
#define PORTB_DATA (*((volatile uint8_t *)0x25))

void init_gpio(void) {
    PORTB_DIR |= (1 << 5);  // Set Pin 5 as output
    PORTB_DATA |= (1 << 5); // Set Pin 5 HIGH
}

// STM32 HAL Timer Interrupt Callback
void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim) {
    if (htim->Instance == TIM2) {
        HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13); // Toggle LED
    }
}

// I2C Sensor Reading in C
void read_sensor_data(uint8_t dev_addr, uint8_t reg_addr, uint8_t *buffer, uint16_t len) {
    i2c_start();
    i2c_write(dev_addr << 1);
    i2c_write(reg_addr);
    i2c_start();
    i2c_write((dev_addr << 1) | 1);
    for (int i = 0; i < len; i++) buffer[i] = i2c_read();
    i2c_stop();
}

// FreeRTOS Task Creation
void vTaskCode(void *pvParameters) {
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}
xTaskCreate(vTaskCode, "SensorTask", 1024, NULL, 1, NULL);
